import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.ShopConfig;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Clock;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class ExpireStaleOrdersTest {

    @Test
    void cancelsOnlyPlacedOrdersOlderThanThirtyDays() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            Instant now = Clock.systemUTC().instant();

            String stale = orders.place("c-1", Money.pln(1000), now.minus(31, ChronoUnit.DAYS));
            String stalePaid = orders.place("c-2", Money.pln(1000), now.minus(40, ChronoUnit.DAYS));
            orders.confirm(stalePaid);
            String fresh = orders.place("c-3", Money.pln(1000), now.minus(29, ChronoUnit.DAYS));

            assertEquals(1, orders.expireStale());

            assertEquals("CANCELLED", orders.summary(stale).status());
            assertEquals("CONFIRMED", orders.summary(stalePaid).status());
            assertEquals("PLACED", orders.summary(fresh).status());
            assertEquals(0, orders.expireStale());
        }
    }
}
}
